@pytest.mark.parametrize(
    "row",
    [r for r in MATRIX["rows"] if r["claim_family"] == "semantic-result"],
    ids=lambda r: r["scope_id"],
)
def test_result_row_is_reached_by_its_named_input(row, tmp_path):
    actual = observe(BY_ID[row["case_id"]], tmp_path)
    assert_answer(actual, ANSWERS[row["case_id"]])
    assert row["scope_id"] in actual["branches"]
